+func probeCWDModeTargets(
+	command shelldecomp.Command,
+	tool string,
+	policy pathlessStdinToolPolicy,
+) cwdModeFact {
+	fact := cwdModeFact{active: true}
+	probeCommand := cwdModeProbeCommand(command, tool, policy)
+	if probeCommand == "" {
+		return fact
+	}
+	probe := parseCommand(probeCommand, command.Cwd, "", nil)
+	for _, target := range probe.ReadTargets() {
+		if target.Argv0 != policy.parseAs {
+			continue
+		}
+		implicitCWD := target.Raw == "." && target.Path == target.Cwd
+		if !implicitCWD {
+			fact.explicitTargets = true
+		}
+		if target.Resolvable && target.Path != shelldecomp.Unresolvable {
+			fact.targets = append(fact.targets, target.Path)
+		}
+	}
+	if fact.explicitTargets {
+		fact.targets = explicitModeTargets(probe.ReadTargets(), policy.parseAs)
+	}
+	return fact
+}
+
+func cwdModeProbeCommand(
+	command shelldecomp.Command,
+	tool string,
+	policy pathlessStdinToolPolicy,
+) string {
+	parseAsParts := strings.Fields(policy.parseAs)
+	toolParts := strings.Fields(tool)
+	if len(parseAsParts) == 0 || len(toolParts) == 0 {
+		return ""
+	}
+	fields := make([]string, 0, len(parseAsParts)+len(command.Args)+2)
+	fields = append(fields, parseAsParts...)
+	fields = append(fields, "-e", shellQuote(searchPathProbe))
+	for index, argument := range command.Args {
+		if index < len(toolParts)-1 {
+			continue
+		}
+		if argumentMatchesCWDFlag(argument.Text, policy.cwdFlags) {
+			continue
+		}
+		fields = append(fields, argument.Text)
+	}
+	return strings.Join(fields, " ")
+}
+
+func argumentMatchesCWDFlag(argument string, cwdFlags map[string]bool) bool {
+	for flag := range cwdFlags {
+		if argument == flag || strings.HasPrefix(argument, flag+"=") {
+			return true
+		}
+	}
+	return false
+}
+
+func explicitModeTargets(targets []shelldecomp.ReadTarget, parseAs string) []string {
+	var paths []string
+	for _, target := range targets {
+		if target.Argv0 != parseAs || target.Raw == "." && target.Path == target.Cwd {
+			continue
+		}
+		if target.Resolvable && target.Path != shelldecomp.Unresolvable {
+			paths = append(paths, target.Path)
+		}
+	}
+	return paths
+}
+
+func configuredCWDModeTargets(facts cwdModeFacts) []string {
+	var targets []string
+	for _, fact := range facts {
+		targets = append(targets, fact.targets...)
+	}

