func assertTemporalField(
	t *testing.T,
	got execconcern.FieldValue,
	field string,
	value string,
	available bool,
) {
	t.Helper()
	if got.Field != field || got.Value != value || got.Available == nil ||
		*got.Available != available {
		t.Fatalf(
			"field = %#v, want field=%q value=%q available=%v",
			got,
			field,

			value,
			available,
		)
	}
}
